local({
  grade <- as.numeric(piat_child_grade)
  case_when(
    grade == 0 & wave == "1990" ~ "Kindergarten or less",
    grade == 0 ~ "Kindergarten",
    grade %in% 1:12 ~ paste("Grade", grade),
    grade == 95 & wave != "1990" ~ "Ungraded",
    .default = NA_character_
  )
})

local({
  self <- rowSums(
    !is.na(tbl[grepl(
      "^(child_(tv|game)_hours_(wd|we|sat|sun)|(child|ya)_comp_hours_week_.+|ya_(tv|game)_hours_week_band)$",
      names(tbl)
    )])
  ) >
    0
  home <- rowSums(!is.na(tbl[grepl("^home_[a-d]_tv_hours_w[de]$", names(tbl))])) > 0
  case_when(self ~ "Self", home ~ "Parent or carer", .default = NA_character_)
})

local({
  self <- rowSums(
    !is.na(tbl[grepl(
      "^(child_(tv|game)_hours_(wd|we|sat|sun)|(child|ya)_comp_hours_week_.+|ya_(tv|game)_hours_week_band)$",
      names(tbl)
    )])
  ) >
    0
  forms <- lapply(tbl[paste0("home_", c("a", "b", "c", "d"), "_tv_hours_we")], function(x) replace(x, x %in% 95, 0))
  lo <- do.call(pmin, c(forms, na.rm = TRUE))
  hi <- do.call(pmax, c(forms, na.rm = TRUE))
  home <- if_else(lo == hi, lo, NA_real_)
  child_tv <- lapply(list(child_tv_hours_wd, child_tv_hours_we, child_tv_hours_sat, child_tv_hours_sun), function(x) {
    replace(replace(x, x %in% 96 & wave == "1996", NA), x %in% 95, 0)
  })
  child_we <- coalesce(child_tv[[2]], (child_tv[[3]] + child_tv[[4]]) / 2)
  if_else(self, child_we, home)
})

local({
  self <- rowSums(
    !is.na(tbl[grepl(
      "^(child_(tv|game)_hours_(wd|we|sat|sun)|(child|ya)_comp_hours_week_.+|ya_(tv|game)_hours_week_band)$",
      names(tbl)
    )])
  ) >
    0
  home_tv <- lapply(c("wd", "we"), function(d) {
    forms <- lapply(tbl[paste0("home_", c("a", "b", "c", "d"), "_tv_hours_", d)], function(x) replace(x, x %in% 95, 0))
    lo <- do.call(pmin, c(forms, na.rm = TRUE))
    hi <- do.call(pmax, c(forms, na.rm = TRUE))
    if_else(lo == hi, lo, NA_real_)
  })
  child_tv <- lapply(list(child_tv_hours_wd, child_tv_hours_we, child_tv_hours_sat, child_tv_hours_sun), function(x) {
    replace(replace(x, x %in% 96 & wave == "1996", NA), x %in% 95, 0)
  })
  child_we <- coalesce(child_tv[[2]], (child_tv[[3]] + child_tv[[4]]) / 2)
  ya <- c(0, 2.5, 7, 12, 17, 22, 27, 32, 35)[as.numeric(ya_tv_hours_week_band)] / 7
  if_else(self, coalesce((child_tv[[1]] * 5 + child_we * 2) / 7, ya), (home_tv[[1]] * 5 + home_tv[[2]] * 2) / 7)
})

local({
  ya <- c(0, 2.5, 7, 12, 17, 22, 27, 32, 35)[as.numeric(ya_game_hours_week_band)] / 7
  coalesce((child_game_hours_wd * 5 + (child_game_hours_sat + child_game_hours_sun) / 2 * 2) / 7, ya)
})

local({
  child <- case_when(
    !is.na(child_comp_hours_week_workschool) ~ child_comp_hours_week_workschool,
    as.numeric(child_comp_ever_uses) %in%
      0 &
      (!is.na(child_tv_hours_week_band) | !is.na(child_game_hours_week_band)) ~ 0
  )
  coalesce(child, ya_comp_hours_week_workschool) / 7
})

local({
  child <- case_when(
    !is.na(child_comp_hours_week_leisure) ~ child_comp_hours_week_leisure,
    as.numeric(child_comp_ever_uses) %in%
      0 &
      (!is.na(child_tv_hours_week_band) | !is.na(child_game_hours_week_band)) ~ 0
  )
  coalesce(child, if_else(wave %in% c("2012", "2014", "2016"), ya_comp_hours_week_leisure, NA_real_)) / 7
})

local({
  self <- rowSums(
    !is.na(tbl[grepl(
      "^(child_(tv|game)_hours_(wd|we|sat|sun)|(child|ya)_comp_hours_week_.+|ya_(tv|game)_hours_week_band)$",
      names(tbl)
    )])
  ) >
    0
  home_tv <- lapply(c("wd", "we"), function(d) {
    forms <- lapply(tbl[paste0("home_", c("a", "b", "c", "d"), "_tv_hours_", d)], function(x) replace(x, x %in% 95, 0))
    lo <- do.call(pmin, c(forms, na.rm = TRUE))
    hi <- do.call(pmax, c(forms, na.rm = TRUE))
    if_else(lo == hi, lo, NA_real_)
  })
  if_else(self, (home_tv[[1]] * 5 + home_tv[[2]] * 2) / 7, NA_real_)
})
